// ─────────────────────────────────────────────────────────────────────────────
// Select Campaigns
// From GET /campaigns/ keep ACTIVE main campaigns (no subsequences), optionally
// limited by CAMPAIGN_IDS and CAMPAIGN_TAG, capped at MAX_CAMPAIGNS_PER_RUN.
// Skipped campaigns are reported (first 50).
// Emits one item per campaign for the per-campaign Smartlead reads.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
// n8n splits a top-level JSON array into one item per element; a wrapped
// response ({ campaigns: [...] }) arrives as one item. Accept both.
const items = $input.all().map((i) => i.json);
if (items.length === 1 && items[0].error) throw new Error(`Smartlead campaign list failed: ${JSON.stringify(items[0].error).slice(0, 200)}`);
const list = items.flatMap((j) => (Array.isArray(j.campaigns) ? j.campaigns : Array.isArray(j.data) ? j.data : (j.id !== undefined ? [j] : [])));
const skipped = [];
const out = [];
for (const c of list) {
  let why = null;
  if (String(c.status).toUpperCase() !== 'ACTIVE') why = 'not_active';
  else if (c.parent_campaign_id) why = 'subsequence';
  else if (cfg.campaignIds.length && !cfg.campaignIds.includes(String(c.id))) why = 'not_in_campaign_ids';
  else if (cfg.campaignTag && !(c.tags || []).some((t) => String(t.tag_name).toLowerCase() === cfg.campaignTag.toLowerCase())) why = 'missing_campaign_tag';
  else if (out.length >= cfg.maxCampaigns) why = 'over_max_campaigns';
  if (why) { if (skipped.length < 50) skipped.push({ campaignId: String(c.id), name: c.name, reason: why }); continue; }
  out.push({ json: { campaignId: String(c.id), name: c.name, status: c.status, skipped } });
}
if (!out.length) return [{ json: { campaignId: null, skipped, listed: list.length } }];
return out;

// ─────────────────────────────────────────────────────────────────────────────
// Collect Campaign Data
// Joins, by item index, each selected campaign with its sequence-analytics
// and sequences responses into the same shape the sandbox produces.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const sel = $('Select Campaigns').all();
const an = $('Smartlead: Get Sequence Analytics').all();
const sq = $input.all();
if (an.length !== sel.length || sq.length !== sel.length) throw new Error(`Campaign data mismatch: ${sel.length} campaigns vs ${an.length} analytics / ${sq.length} sequences responses. Unpin the Smartlead read nodes or align their items.`);
const campaigns = sel.map((s, i) => ({
  campaignId: s.json.campaignId, name: s.json.name, status: s.json.status,
  analytics: an[i].json.error ? null : an[i].json,
  sequences: sq[i].json.error ? null : sq[i].json,
  readErrors: [an[i].json.error ? 'sequence_analytics_failed' : null, sq[i].json.error ? 'sequences_failed' : null].filter(Boolean),
}));
return [{ json: { source: 'smartlead', window: { start: cfg.windowStart, end: cfg.windowEnd }, campaigns, skipped: sel[0].json.skipped || [] } }];

// ─────────────────────────────────────────────────────────────────────────────
// Statistical Evaluation
// Per campaign step with 2+ variants:
//   1. Sample gate: every variant needs ≥ MIN_SAMPLE_SIZE sends in the window.
//   2. Leader = highest rate on TEST_METRIC (reply | positive_reply).
//   3. Each challenger vs. the leader: two-proportion z-test (pooled), one-sided
//      p-value, Bonferroni-adjusted alpha = ALPHA / (k − 1).
//   4. A challenger is a loser only if p < adjusted alpha AND the leader's
//      relative lift ≥ MIN_RELATIVE_LIFT.
//   5. Guardrails on the leader: ≥ MIN_WINNER_EVENTS events, rate ≥
//      MIN_WINNER_RATE_PCT, bounce ≤ MAX_BOUNCE_RATE_PCT. Cooldown per step.
// Decision per step:
//   promote_winner  — every challenger is a loser → winner takes the traffic
//   pause_losers    — some challengers lose, others are inconclusive
//   keep_running    — inconclusive / insufficient sample / guardrail
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const data = $input.first().json;

// Standard normal upper tail via erfc (Abramowitz & Stegun 7.1.26, |error| < 1.5e-7).
const erfc = (x) => {
  const z = Math.abs(x); const t = 1 / (1 + 0.3275911 * z);
  const y = t * (0.254829592 + t * (-0.284496736 + t * (1.421413741 + t * (-1.453152027 + t * 1.061405429)))) * Math.exp(-z * z);
  return x >= 0 ? y : 2 - y;
};
const upperTail = (z) => 0.5 * erfc(z / Math.SQRT2);
const zTest = (x1, n1, x2, n2) => {
  const p1 = x1 / n1; const p2 = x2 / n2; const p = (x1 + x2) / (n1 + n2);
  const se = Math.sqrt(p * (1 - p) * (1 / n1 + 1 / n2));
  if (!(se > 0)) return { z: 0, p: 1 };
  const z = (p1 - p2) / se;
  return { z, p: upperTail(z) };
};
const r4 = (x) => Math.round(x * 10000) / 10000;

let store = null;
try { store = $getWorkflowStaticData('global'); } catch (e) { store = null; }
const changes = (store && store.lastChange) || {};

const results = [];
for (const c of data.campaigns) {
  const camp = { campaignId: c.campaignId, name: c.name, steps: [], errors: [...(c.readErrors || [])] };
  const seqs = c.analytics?.data?.sequences || [];
  if (!c.analytics) camp.errors.push('no_analytics');
  for (const s of seqs) {
    const vars = (s.variants || []).map((v) => {
      const st = v.stats || {};
      const n = Number(st.sent_count) || 0;
      const x = Number(cfg.testMetric === 'positive_reply' ? st.positive_reply_count : st.reply_count) || 0;
      return { variantId: String(v.id), label: String(v.variant_label || v.id), isBaseline: Boolean(v.is_baseline), sent: n, events: x, rate: n ? x / n : 0, bouncePct: Number(st.bounce_percentage) || 0 };
    });
    const step = { stepId: String(s.id), seqNumber: s.seq_number, variants: vars, decision: 'keep_running', reason: null, winner: null, losers: [], inconclusive: [], comparisons: [] };
    camp.steps.push(step);
    if (vars.length < 2) { step.reason = 'single_variant'; continue; }
    const small = vars.filter((v) => v.sent < cfg.minSampleSize);
    if (small.length) { step.reason = `insufficient_sample (${small.map((v) => `${v.label}:${v.sent}`).join(', ')} < ${cfg.minSampleSize})`; continue; }

    const sorted = [...vars].sort((a, b) => b.rate - a.rate || b.sent - a.sent);
    const leader = sorted[0];
    const k = vars.length;
    const alphaAdj = cfg.alpha / (k - 1);
    for (const ch of sorted.slice(1)) {
      const t = zTest(leader.events, leader.sent, ch.events, ch.sent);
      const lift = ch.rate > 0 ? (leader.rate - ch.rate) / ch.rate : (leader.rate > 0 ? Infinity : 0);
      const significant = t.p < alphaAdj && lift >= cfg.minRelativeLift;
      step.comparisons.push({ leader: leader.label, challenger: ch.label, leaderRate: r4(leader.rate), challengerRate: r4(ch.rate), z: Math.round(t.z * 100) / 100, pValue: Number(t.p.toExponential(3)), alphaAdjusted: Number(alphaAdj.toPrecision(3)), relativeLift: Number.isFinite(lift) ? Math.round(lift * 1000) / 1000 : null, significant });
      (significant ? step.losers : step.inconclusive).push(ch.variantId);
    }
    step.leader = leader.variantId;

    // Guardrails on the leader
    const key = `${c.campaignId}:${s.id}`;
    const last = changes[key];
    if (!step.losers.length) { step.reason = 'no_significant_difference'; continue; }
    if (leader.events < cfg.minWinnerEvents) { step.reason = `leader_below_min_events (${leader.events} < ${cfg.minWinnerEvents})`; continue; }
    if (leader.rate * 100 < cfg.minWinnerRatePct) { step.reason = `leader_below_rate_threshold (${(leader.rate * 100).toFixed(2)}% < ${cfg.minWinnerRatePct}%)`; continue; }
    if (leader.bouncePct > cfg.maxBounceRatePct) { step.reason = `leader_bounce_rate_too_high (${leader.bouncePct}% > ${cfg.maxBounceRatePct}%)`; continue; }
    if (last && Date.now() - last < cfg.cooldownDays * 86400000) { step.reason = `cooldown (changed ${Math.floor((Date.now() - last) / 86400000)}d ago)`; continue; }

    step.winner = step.inconclusive.length ? null : leader.variantId;
    step.decision = step.inconclusive.length ? 'pause_losers' : 'promote_winner';
    step.reason = step.inconclusive.length ? `${step.losers.length} significant loser(s), ${step.inconclusive.length} still inconclusive` : `all ${k - 1} challenger(s) significantly worse`;
  }
  results.push(camp);
}
const all = results.flatMap((c) => c.steps);
const counts = { campaigns: results.length, steps: all.length, tested: all.filter((s) => s.variants.length > 1).length, promote_winner: all.filter((s) => s.decision === 'promote_winner').length, pause_losers: all.filter((s) => s.decision === 'pause_losers').length, keep_running: all.filter((s) => s.decision === 'keep_running' && s.variants.length > 1).length };
return [{ json: { source: data.source, window: data.window, skipped: data.skipped, counts, campaigns: results } }];

// ─────────────────────────────────────────────────────────────────────────────
// Compose Variant Changes
// Turns step decisions into one Smartlead "save sequences" payload per campaign.
// Smartlead saves the whole sequence, so every step is rebuilt from
// GET /campaigns/{id}/sequences with its id, copy and delay unchanged. Only the
// decided steps get a new MANUAL_PERCENTAGE split:
//   losers       → LOSER_FLOOR_PERCENT (0 = paused)
//   inconclusive → current share, rounded down to a multiple of 10 (min 10)
//   leader       → the remainder
// Smartlead only honours multiples of 10 in manual splits.
// Pre-flight checks block a campaign instead of sending a partial payload.
// An untouched multi-variant step whose split the API doesn't expose blocks
// the campaign unless ALLOW_EQUAL_SPLIT_ASSUMPTION=true.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const ev = $input.first().json;
const SHARE_KEYS = ['variant_distribution_percentage', 'distribution_percentage', 'distribution', 'variant_distribution'];
const shareOf = (v) => { for (const k of SHARE_KEYS) if (Number.isFinite(Number(v[k])) && v[k] !== null && v[k] !== '') return Number(v[k]); return null; };
const labelOf = (v) => String(v.variant_label || v.variant_name || '').replace(/^variant\s+/i, '').trim();
const fromData = $('Mock Smartlead Data').isExecuted ? $('Mock Smartlead Data').first().json : $('Collect Campaign Data').first().json;
const byId = new Map(fromData.campaigns.map((c) => [c.campaignId, c]));

const mutations = [];
const blocked = [];
const changes = [];
for (const camp of ev.campaigns) {
  const decided = camp.steps.filter((s) => s.decision !== 'keep_running');
  if (!decided.length) continue;
  const raw = byId.get(camp.campaignId);
  const steps = raw?.sequences?.data;
  const block = (reason) => blocked.push({ campaignId: camp.campaignId, name: camp.name, reason });
  if (!Array.isArray(steps) || !steps.length) { block('sequences_unavailable'); continue; }
  if (steps.some((st) => typeof st.email_body !== 'string' || !st.email_body.trim())) { block('step_without_email_body (refusing to rewrite copy)'); continue; }

  const notes = [];
  let ok = true;
  const payloadSteps = steps.map((st) => {
    const sv = Array.isArray(st.sequence_variants) ? st.sequence_variants : (Array.isArray(st.seq_variants) ? st.seq_variants : []);
    const base = { id: st.id, seq_number: st.seq_number, subject: st.subject ?? '', email_body: st.email_body, seq_delay_details: { delay_in_days: Number(st.seq_delay_details?.delayInDays ?? st.seq_delay_details?.delay_in_days ?? 0) } };
    if (sv.length < 2) return base;
    const d = decided.find((x) => String(x.stepId) === String(st.id) || x.seqNumber === st.seq_number);
    const current = sv.map(shareOf);
    const known = current.every((x) => x !== null);
    if (!d) {
      if (known) return { ...base, variant_distribution_type: 'MANUAL_PERCENTAGE', seq_variants: sv.map((v, i) => ({ id: v.id, subject: v.subject ?? '', email_body: v.email_body, variant_label: labelOf(v), variant_distribution_percentage: current[i] })) };
      if (!cfg.allowEqualSplitAssumption) { ok = false; notes.push(`step ${st.seq_number}: has ${sv.length} variants but its current split is not exposed by the API; saving would reset it (set ALLOW_EQUAL_SPLIT_ASSUMPTION=true to accept MANUAL_EQUAL)`); return base; }
      notes.push(`step ${st.seq_number}: current split not exposed by the API, saved as MANUAL_EQUAL`);
      return { ...base, variant_distribution_type: 'MANUAL_EQUAL', seq_variants: sv.map((v) => ({ id: v.id, subject: v.subject ?? '', email_body: v.email_body, variant_label: labelOf(v) })) };
    }
    // Match analytics variants to sequence variants: id first, then label.
    const find = (aid) => {
      const a = d.variants.find((x) => x.variantId === aid);
      return sv.findIndex((v) => String(v.id) === aid || (a && labelOf(v).toLowerCase() === a.label.toLowerCase()));
    };
    const idxLeader = find(d.leader);
    const idxLosers = d.losers.map(find);
    const idxInc = d.inconclusive.map(find);
    if ([idxLeader, ...idxLosers, ...idxInc].some((i) => i < 0) || idxLosers.length + idxInc.length + 1 !== sv.length) {
      ok = false; notes.push(`step ${st.seq_number}: analytics variants do not match the sequence variants`); return base;
    }
    const eq = 100 / sv.length;
    const share = sv.map((_, i) => (known ? current[i] : eq));
    const next = sv.map(() => 0);
    for (const i of idxLosers) next[i] = cfg.loserFloorPercent;
    for (const i of idxInc) next[i] = Math.max(10, Math.floor(share[i] / 10) * 10);
    next[idxLeader] = 100 - next.reduce((a, b) => a + b, 0);
    if (next[idxLeader] < 10 || next.some((x) => x % 10 !== 0) || next.reduce((a, b) => a + b, 0) !== 100) { ok = false; notes.push(`step ${st.seq_number}: no valid multiple-of-10 split`); return base; }
    const label = (i) => labelOf(sv[i]) || String(sv[i].id);
    changes.push({
      campaignId: camp.campaignId, campaign: camp.name, stepId: String(st.id), seqNumber: st.seq_number, decision: d.decision,
      winner: d.winner ? label(idxLeader) : null, leader: label(idxLeader),
      before: Object.fromEntries(sv.map((_, i) => [label(i), Math.round(share[i])])), after: Object.fromEntries(sv.map((_, i) => [label(i), next[i]])),
      comparisons: d.comparisons, assumedEqualSplit: !known,
    });
    return { ...base, variant_distribution_type: 'MANUAL_PERCENTAGE', seq_variants: sv.map((v, i) => ({ id: v.id, subject: v.subject ?? '', email_body: v.email_body, variant_label: labelOf(v), variant_distribution_percentage: next[i] })) };
  });
  if (!ok) { block(notes.join('; ')); for (let i = changes.length - 1; i >= 0; i -= 1) if (changes[i].campaignId === camp.campaignId) changes.splice(i, 1); continue; }
  mutations.push({ campaignId: camp.campaignId, name: camp.name, notes, payload: { sequences: payloadSteps } });
}
return [{ json: { ...ev, changes, mutations, blocked, changeCount: changes.length } }];

// ─────────────────────────────────────────────────────────────────────────────
// Collect Mutation Results
// Joins, by index, the pause → save → resume responses per campaign. A
// campaign counts as applied only when the save succeeded; the resume result
// is reported separately so a stuck pause is never silent. Records the change
// time per step (production executions only) for COOLDOWN_DAYS.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const muts = $('Emit Campaign Mutations').all();
const pause = $('Smartlead: Pause Campaign').all();
const save = $('Smartlead: Save Sequence Split').all();
const resume = $input.all();
if ([pause, save, resume].some((a) => a.length !== muts.length)) throw new Error(`Mutation result mismatch: ${muts.length} campaigns vs ${pause.length}/${save.length}/${resume.length} responses.`);
const failed = (j) => Boolean(j.error) || j.ok === false || j.success === false;
const results = muts.map((m, i) => ({
  campaignId: m.json.campaignId, name: m.json.name,
  paused: !failed(pause[i].json), saved: !failed(save[i].json), resumed: !failed(resume[i].json),
  error: failed(save[i].json) ? String(save[i].json.error?.message || save[i].json.message || save[i].json.error || 'save_failed').slice(0, 200) : null,
}));
let store = null;
try { store = $getWorkflowStaticData('global'); } catch (e) { store = null; }
if (store && cfg.executionMode === 'production') {
  store.lastChange = store.lastChange || {};
  const changes = $('Compose Variant Changes').first().json.changes;
  for (const r of results.filter((x) => x.saved)) for (const ch of changes.filter((c) => c.campaignId === r.campaignId)) store.lastChange[`${ch.campaignId}:${ch.stepId}`] = Date.now();
}
return [{ json: { results, applied: results.filter((r) => r.saved).length, failed: results.filter((r) => !r.saved).length, notResumed: results.filter((r) => !r.resumed).map((r) => r.campaignId) } }];

// ─────────────────────────────────────────────────────────────────────────────
// Build Notification
// One Slack Block Kit message and one webhook JSON per run, describing what
// was decided and what actually happened (applied / dry run / sandbox /
// failed). Contains campaign names, variant labels and rates, no lead data.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const cmp = $('Compose Variant Changes').first().json;
let mut = null;
try { mut = $('Collect Mutation Results').isExecuted ? $('Collect Mutation Results').first().json : null; } catch (e) { mut = null; }
const mode = cfg.sandboxMode ? 'SANDBOX (synthetic data, nothing changed)' : cfg.promoteWinners ? 'LIVE (changes applied)' : 'DRY RUN (recommendations only)';
const pct = (x) => `${(x * 100).toFixed(2)}%`;
const statusOf = (cid) => {
  if (!mut) return cfg.promoteWinners ? 'not_applied' : 'recommended';
  const r = mut.results.find((x) => x.campaignId === cid);
  if (!r) return 'not_applied';
  return r.saved ? (r.resumed ? 'applied' : 'applied_but_not_resumed') : (r.resumed ? 'failed_resumed' : 'failed_campaign_paused');
};
const kept = cmp.campaigns.flatMap((c) => c.steps.filter((s) => s.decision === 'keep_running' && s.variants.length > 1).map((s) => ({ campaign: c.name, seq: s.seqNumber, reason: s.reason })));

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: 'Smartlead A/B auto-promoter', emoji: true } },
  { type: 'context', elements: [{ type: 'mrkdwn', text: `*${mode}* · metric \`${cfg.testMetric}\` · window ${cfg.windowDays}d · min ${cfg.minSampleSize} sends/variant · α ${cfg.alpha}` }] },
  { type: 'section', text: { type: 'mrkdwn', text: `*${cmp.counts.promote_winner}* winner(s) promoted · *${cmp.counts.pause_losers}* step(s) with losers paused · *${cmp.counts.keep_running}* still running · ${cmp.blocked.length} blocked` } },
];
for (const ch of cmp.changes.slice(0, 15)) {
  const lines = ch.comparisons.map((x) => `• ${x.leader} ${pct(x.leaderRate)} vs ${x.challenger} ${pct(x.challengerRate)} · p=${x.pValue} ${x.significant ? '✅' : '…'}`).join('\n');
  const split = Object.entries(ch.after).map(([k, v]) => `${k} ${ch.before[k]}→${v}%`).join(' · ');
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `${ch.decision === 'promote_winner' ? '🏆' : '✂️'} *${ch.campaign}* · step ${ch.seqNumber} · \`${statusOf(ch.campaignId)}\`\n${split}${ch.assumedEqualSplit ? ' _(prior split assumed equal)_' : ''}\n${lines}`.slice(0, 2900) } });
}
if (cmp.blocked.length) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `⛔ *Blocked*\n${cmp.blocked.map((b) => `• ${b.name}: ${b.reason}`).join('\n')}`.slice(0, 2900) } });
if (mut && mut.notResumed.length) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `🚨 *Campaigns may still be PAUSED:* ${mut.notResumed.join(', ')}. Resume them in Smartlead.` } });
if (kept.length) blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `Still running: ${kept.slice(0, 8).map((k) => `${k.campaign} s${k.seq} (${k.reason})`).join(' · ')}`.slice(0, 2900) }] });
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `n8n run ${cfg.runId}` }] });

const worthNotifying = cmp.changes.length > 0 || cmp.blocked.length > 0 || (mut && mut.failed > 0) || cfg.notifyOnNoChange;
const summary = `A/B auto-promoter: ${cmp.counts.promote_winner} promoted, ${cmp.counts.pause_losers} with losers paused, ${cmp.counts.keep_running} running (${mode}).`;
return [{ json: {
  worthNotifying,
  slackBody: { text: summary, blocks },
  webhookBody: { event: 'smartlead.ab_test.evaluated', generatedAt: new Date().toISOString(), runId: cfg.runId, mode: cfg.sandboxMode ? 'sandbox' : cfg.promoteWinners ? 'live' : 'dry_run',
    settings: { metric: cfg.testMetric, windowDays: cfg.windowDays, minSampleSize: cfg.minSampleSize, alpha: cfg.alpha, minRelativeLift: cfg.minRelativeLift, loserFloorPercent: cfg.loserFloorPercent },
    counts: cmp.counts, changes: cmp.changes.map((c) => ({ ...c, status: statusOf(c.campaignId) })), blocked: cmp.blocked, stillRunning: kept },
} }];

// ─────────────────────────────────────────────────────────────────────────────
// Execution Summary & Audit
// Final record on every path. No secrets, no lead data.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const one = (n) => { try { return $(n).isExecuted ? $(n).first().json : null; } catch (e) { return null; } };
const all = (n) => { try { return $(n).isExecuted ? $(n).all().map((i) => i.json) : []; } catch (e) { return []; } };
const ev = one('Statistical Evaluation');
const cmp = one('Compose Variant Changes');
const mut = one('Collect Mutation Results');
const sl = all('Slack: Post Summary');
const wh = all('Webhook: Post Summary');
const sel = one('Mock Smartlead Data') || one('Collect Campaign Data') || {};

let outcome = 'no_tests_evaluated';
if (ev && cmp) {
  if (!cmp.changes.length) outcome = cmp.blocked.length ? 'changes_blocked' : 'no_changes_needed';
  else if (cfg.sandboxMode) outcome = 'changes_found_sandbox';
  else if (!cfg.promoteWinners) outcome = 'changes_recommended_dry_run';
  else if (mut && mut.failed) outcome = mut.notResumed.length ? 'changes_failed_campaign_paused' : 'changes_partially_applied';
  else outcome = 'changes_applied';
}
return [{ json: {
  workflow: 'n8n-smartlead-campaign-ab-test-winner-auto-promoter',
  runId: cfg.runId, executionMode: cfg.executionMode, finishedAt: new Date().toISOString(), outcome,
  safety: { sandboxMode: cfg.sandboxMode, dryRun: cfg.dryRun, promoteWinners: cfg.promoteWinners },
  settings: { metric: cfg.testMetric, windowDays: cfg.windowDays, minSampleSize: cfg.minSampleSize, alpha: cfg.alpha, minRelativeLift: cfg.minRelativeLift, minWinnerRatePct: cfg.minWinnerRatePct, minWinnerEvents: cfg.minWinnerEvents, maxBounceRatePct: cfg.maxBounceRatePct, loserFloorPercent: cfg.loserFloorPercent, cooldownDays: cfg.cooldownDays },
  source: sel.source || null, window: sel.window || null,
  campaignsSkipped: sel.skipped || [],
  counts: ev ? ev.counts : null,
  steps: ev ? ev.campaigns.flatMap((c) => c.steps.filter((s) => s.variants.length > 1).map((s) => ({ campaignId: c.campaignId, step: s.seqNumber, decision: s.decision, reason: s.reason, variants: s.variants.map((v) => `${v.label}:${v.events}/${v.sent}`) }))) : [],
  changes: cmp ? cmp.changes.map((c) => ({ campaignId: c.campaignId, step: c.seqNumber, decision: c.decision, before: c.before, after: c.after })) : [],
  blocked: cmp ? cmp.blocked : [],
  mutations: mut ? mut.results : [],
